jsonTools.init:
function init(eli) {
  eli = eli || window.eli;
  if (!eli || !eli.register) return;

  // 2026-06-09: opened to all users (was andrew-only alpha). The strip
  // is OFF by default — users opt in via the 🧩 manager (tile or
  // Settings → Interface → Dashboard Widgets).

  // ── Kill switch ───────────────────────────────────────────────────
  try {
    eli.settings.register("dashboard_widgets_enabled", {
      default: true, type: "boolean", adminPushable: true,
      describe: "Dashboard widgets strip enabled",
    });
  } catch (_) {}
  function _featureOn() {
    try { return eli.settings.get("dashboard_widgets_enabled") !== false; }
    catch (_) { return true; }
  }

  // ── Layout persistence — config store, canonical {key, value} shape ─
  var LAYOUT_KEY = "widget_layout";
  var _layout = null; // { master, enabled:{}, order:[], sizes:{} }
  // Hard cap — exactly two widget boxes side by side, so the
  // dashboard's vertical height never changes with widget count.
  var MAX_ACTIVE = 2;
  function _defaultLayout() {
    return {
      // master:false — widgets are opt-in (off for new users). 2026-06-13:
      // no widget is pre-checked either; checking one in the manager
      // auto-enables the master toggle (see tgl.onchange below).
      master: false,
      enabled: { word_day: false, trivia_day: false, joke_day: false, case_day: false, patent_day: false, tip_day: false, playbook_day: false },
      order: ["word_day", "trivia_day", "joke_day", "case_day", "patent_day", "tip_day", "playbook_day"],
      sizes: {},
      variants: {},   // per-widget content variant (e.g. contract|patent)
    };
  }
  function _activeCount() {
    if (!_layout) return 0;
    var n = 0;
    _layout.order.forEach(function (id) {
      if (_layout.enabled[id] && _findWidget(id)) n++;
    });
    return n;
  }
  function _loadLayout() {
    return eli.storage.get("config", LAYOUT_KEY).then(function (row) {
      var v = (row && row.value) || {};
      var d = _defaultLayout();
      _layout = {
        master:   v.master === undefined ? d.master : !!v.master,
        enabled:  v.enabled || d.enabled,
        order:    Array.isArray(v.order) && v.order.length ? v.order : d.order,
        sizes:    v.sizes || {},
        variants: v.variants || {},
      };
      // Widgets shipped after the user's layout was first saved would
      // otherwise never appear in the manager — append missing ids.
      d.order.forEach(function (id) {
        if (_layout.order.indexOf(id) === -1) _layout.order.push(id);
      });
      return _layout;
    }).catch(function () { _layout = _defaultLayout(); return _layout; });
  }
  function _saveLayout() {
    return eli.storage.put("config", { key: LAYOUT_KEY, value: _layout, updatedAt: Date.now() })
      .catch(function () {});
  }

  // ── Deterministic daily index — same item all day, rotates at local
  //    midnight. Whole team would see the same item (shared watercooler).
  function _curDoy() {
    var now = new Date();
    var start = new Date(now.getFullYear(), 0, 0);
    return Math.floor((now - start) / 86400000);
  }
  function _dayIndex(len, salt) {
    if (!len) return 0;
    return (_curDoy() + (salt || 0)) % len;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // ── Content: Word of the Day ──────────────────────────────────────
  var WORDS = [
    { t: "Force Majeure", d: "Excuses performance when extraordinary events beyond the parties' control intervene.", w: "List the triggering events — courts read these clauses narrowly." },
    { t: "Indemnification", d: "One party's promise to cover another's losses from specified claims.", w: "Watch the trio: scope, cap, and defense obligation — each is negotiated separately." },
    { t: "Novation", d: "Replacing a party (or obligation) with a new one, extinguishing the original.", w: "Unlike assignment, novation needs everyone's consent — including the party staying put." },
    { t: "Estoppel", d: "Bars a party from contradicting what it previously asserted when others relied on it.", w: "Your emails during a deal can estop your litigation position later." },
    { t: "Contra Proferentem", d: "Ambiguity is construed against the party that drafted it.", w: "The hidden tax on sloppy drafting — and a reason templates get audited." },
    { t: "Quantum Meruit", d: "Recovery of the reasonable value of services when no enforceable contract covers them.", w: "It's the fallback when work started before the contract was signed." },
    { t: "Severability", d: "If one clause fails, the rest of the agreement survives.", w: "Without it, one unenforceable term can take the whole contract down." },
    { t: "Consideration", d: "The bargained-for exchange that makes a promise enforceable.", w: "Recitals of $1 usually work — past consideration usually doesn't." },
    { t: "Peppercorn", d: "Nominal consideration — trivially small but legally sufficient.", w: "Courts ask whether consideration exists, not whether the deal was wise." },
    { t: "Condition Precedent", d: "An event that must occur before a duty to perform arises.", w: "Spot the difference between a promise (breach = damages) and a condition (no duty at all)." },
    { t: "Liquidated Damages", d: "Pre-agreed damages for a specific breach.", w: "Enforceable as a reasonable estimate — struck down as a penalty if punitive." },
    { t: "Integration Clause", d: "Declares the written agreement the complete and final deal.", w: "It activates the parol evidence rule — side emails stop counting." },
    { t: "Tolling", d: "Pausing the running of a limitations period.", w: "Tolling agreements buy negotiation time without losing claims." },
    { t: "Waiver", d: "Intentional relinquishment of a known right.", w: "'No-waiver' clauses exist because accepting late payment twice can waive timeliness." },
    { t: "Material Breach", d: "A failure serious enough to excuse the other side's performance.", w: "Materiality decides whether you can walk away or only sue for damages." },
    { t: "Cure Period", d: "Time given to fix a breach before remedies kick in.", w: "Notice-and-cure turns 'gotcha' terminations into negotiations." },
    { t: "Covenant", d: "A promise to do (affirmative) or not do (negative) something.", w: "Non-competes are negative covenants — scope and duration drive enforceability." },
    { t: "Recitals", d: "The 'whereas' clauses describing background and intent.", w: "Usually not binding — but courts read them when operative terms are ambiguous." },
    { t: "Counterparts", d: "Permits signing in separate copies that together form one agreement.", w: "The clause that quietly blesses scattered e-signatures." },
    { t: "Ipso Facto", d: "'By the fact itself' — clauses triggered automatically by an event, like bankruptcy.", w: "Ipso facto termination-on-bankruptcy clauses are largely unenforceable in bankruptcy." },
    { t: "Pari Passu", d: "'On equal footing' — obligations rank equally without preference.", w: "A lender phrase that migrates into IP and payment waterfall clauses." },
    { t: "Time Is of the Essence", d: "Makes timely performance a material term.", w: "Without it, 'late' is usually a damages problem, not a termination right." },
    { t: "Assignment", d: "Transferring contract rights to a third party.", w: "Anti-assignment clauses often carve out affiliates and M&A — read the carve-outs first." },
    { t: "Representations & Warranties", d: "Statements of fact (reps) and promises they're true (warranties).", w: "Reps support fraud claims; warranties support breach claims — survival periods differ." },
  ];

  // ── Content: Trivia of the Day ────────────────────────────────────
  var TRIVIA = [
    { q: "In Leonard v. Pepsico, a man sued for the Harrier jet shown in a Pepsi Points ad. The court held the ad was…", a: ["An obvious joke — no offer", "A binding unilateral offer", "An invitation to negotiate only"], c: 0, x: "The court found no objective person could believe a $23M fighter jet came with 7,000,000 Pepsi Points. The 'offer' failed as a matter of law." },
    { q: "A missing Oxford comma in a Maine dairy's overtime statute famously cost the company about…", a: ["$5 million", "$50,000", "$500 million"], c: 0, x: "O'Connor v. Oakhurst Dairy (2017) — 'packing for shipment or distribution' was ambiguous without the comma; the case settled for $5M." },
    { q: "Carlill v. Carbolic Smoke Ball Co. established that a public ad promising payment can be…", a: ["A unilateral offer accepted by performance", "Mere puffery, never binding", "Valid only if individually addressed"], c: 0, x: "Mrs. Carlill used the smoke ball, caught influenza anyway, and the £100 reward was enforceable — the ad was an offer to the world." },
    { q: "Van Halen's contracts demanded a bowl of M&Ms with the brown ones removed. The clause's real purpose was…", a: ["A safety-compliance canary", "Pure rock-star ego", "A merchandising tie-in"], c: 0, x: "Buried in dense technical riders, brown M&Ms revealed whether the venue had actually read the safety specs for their massive stage rig." },
    { q: "Hadley v. Baxendale limits consequential damages to losses that were…", a: ["Foreseeable at contract formation", "Actually suffered, however remote", "Under £100"], c: 0, x: "The broken mill shaft case (1854) — special circumstances must be communicated up front, which is why limitation-of-liability clauses recite them." },
    { q: "Under the mailbox rule, an acceptance is generally effective when…", a: ["Dispatched", "Received", "Read"], c: 0, x: "Acceptance on dispatch; revocation on receipt. Modern contracts often override it by requiring notice to be 'effective on receipt.'" },
    { q: "The Statute of Frauds generally requires a writing for contracts that cannot be performed within…", a: ["One year", "Six months", "Thirty days"], c: 0, x: "The one-year rule is read narrowly: if performance within a year is conceivably possible, no writing is required." },
    { q: "The UCC's 'battle of the forms' provision is…", a: ["§ 2-207", "§ 1-103", "§ 9-401"], c: 0, x: "It decides whose boilerplate wins when purchase orders and acknowledgments conflict — and why 'last shot' doctrine faded for goods." },
    { q: "A liquidated damages clause is unenforceable when a court finds it operates as…", a: ["A penalty", "An estimate", "A cap"], c: 0, x: "The test: reasonable forecast of hard-to-measure harm at formation. In terrorem amounts get struck." },
    { q: "Specific performance is most readily granted for contracts involving…", a: ["Land and unique goods", "Commodity sales", "Employment services"], c: 0, x: "Money damages suffice for fungibles; uniqueness makes them inadequate. Courts won't order people to work — that's involuntary servitude territory." },
    { q: "The parol evidence rule bars…", a: ["Prior agreements contradicting an integrated writing", "All oral testimony in contract cases", "Evidence of fraud"], c: 0, x: "It protects final writings from being rewritten by negotiation history — but fraud, ambiguity, and condition-precedent evidence still come in." },
    { q: "'Four corners' interpretation means a court looks…", a: ["Only at the document itself", "At industry custom first", "At the parties' emails"], c: 0, x: "If the writing is unambiguous, extrinsic evidence stays out. Ambiguity is the doorway through which everything else enters." },
    { q: "An option contract differs from a plain offer because it…", a: ["Is supported by consideration and irrevocable", "Must be in writing", "Cannot expire"], c: 0, x: "Paying to hold an offer open makes revocation a breach. Without consideration, offers are freely revocable before acceptance." },
    { q: "In contract law, a 'peppercorn' refers to…", a: ["Nominal but sufficient consideration", "A minor breach", "A boilerplate clause"], c: 0, x: "Courts don't weigh the adequacy of consideration — a peppercorn will do, which is why $1 recitals persist." },
    { q: "The 'mirror image' rule requires that an acceptance…", a: ["Match the offer exactly", "Be in the same medium as the offer", "Be notarized"], c: 0, x: "Any variation makes it a counteroffer at common law. The UCC relaxed this for goods — hence § 2-207's existence." },
    { q: "Promissory estoppel allows enforcement of a promise without…", a: ["Consideration", "Reliance", "A promisor"], c: 0, x: "Reasonable, detrimental reliance substitutes for the bargain. It's the safety net under gratuitous promises." },
    { q: "A contract signed under economic duress is…", a: ["Voidable by the coerced party", "Automatically void", "Fully enforceable"], c: 0, x: "Voidable, not void — the victim chooses whether to rescind, and ratification by performance can waive the defense." },
    { q: "'Efficient breach' theory says a party should breach when…", a: ["Paying damages costs less than performing", "The other side breaches first", "A better lawyer is available"], c: 0, x: "Law-and-economics' most provocative idea: expectation damages make some breaches socially efficient. Liquidated damages clauses push back." },
  ];

  // ── Content: Joke of the Day ──────────────────────────────────────
  var JOKES = [
    { s: "Why did the contract go to therapy?", p: "It had too many unresolved issues." },
    { s: "I'd tell you a confidentiality joke…", p: "…but you'd have to sign an NDA first." },
    { s: "What did the indemnification clause say at the party?", p: "\"Don't worry — I've got you covered.\"" },
    { s: "Why did the clause break up with the sentence?", p: "It needed more consideration." },
    { s: "What's a contract's favorite love story?", p: "An offer and an acceptance." },
    { s: "Why was the boilerplate so calm?", p: "Nothing ever changed it." },
    { s: "How does a contract say goodbye?", p: "\"Termination for convenience.\"" },
    { s: "Why did the warranty blush?", p: "It got disclaimed in ALL CAPS." },
    { s: "Why are amendments so polite?", p: "They always ask both parties before changing anything." },
    { s: "What's the integration clause's dating profile?", p: "\"Supersedes all prior relationships, written or oral.\"" },
    { s: "The statute of limitations walked into a bar…", p: "…eventually." },
    { s: "What's severability's motto?", p: "\"If one of us falls, the rest carry on.\"" },
    { s: "Why does force majeure never get invited to parties?", p: "It only shows up when everything goes wrong." },
    { s: "What's the most optimistic phrase in contract law?", p: "\"Best efforts.\"" },
    { s: "Why did the deadline say \"time is of the essence\"?", p: "Because nobody was taking it literally." },
    { s: "What did one redline say to the other?", p: "\"I don't think we're aligned.\"" },
    { s: "Why do recitals make terrible witnesses?", p: "Everything they say is non-binding." },
    { s: "What did the counterparty say to the 47-page MSA?", p: "\"Let's just say we're reviewing it.\"" },
    { s: "Why was the cure period feeling generous?", p: "It always gives people 30 more days." },
    { s: "How do you comfort a frustrated contract?", p: "\"There, there — impossibility excuses us all sometimes.\"" },
    { s: "Why did the e-signature feel unappreciated?", p: "People kept asking if it was \"really\" binding. (It is.)" },
  ];

  // ── Content: Patent Trivia ────────────────────────────────────────
  var PATENT_TRIVIA = [
    { q: "A US utility patent's term runs…", a: ["20 years from the earliest filing date", "17 years from grant", "25 years from publication"], c: 0, x: "Since 1995 (TRIPS/URAA): 20 years from filing, not 17 from grant — which killed the 'submarine patent' strategy of keeping applications pending for decades." },
    { q: "The first US patent (1790) was examined and signed by…", a: ["Thomas Jefferson (and signed by George Washington)", "Benjamin Franklin", "Alexander Hamilton"], c: 0, x: "Jefferson personally examined early patents as Secretary of State. Patent No. X1 went to Samuel Hopkins for an improved potash process." },
    { q: "A provisional patent application expires after…", a: ["12 months", "18 months", "5 years"], c: 0, x: "It's a placeholder, never examined. Miss the 12-month conversion window and the priority date evaporates — the classic startup catastrophe." },
    { q: "The America Invents Act (2013) switched the US to…", a: ["First-inventor-to-file", "First-to-invent", "First-to-publish"], c: 0, x: "Ending two centuries of first-to-invent. The race to the Patent Office now matters more than the lab notebook." },
    { q: "Under §101, the four categories of patentable subject matter are process, machine, manufacture, and…", a: ["Composition of matter", "Business method", "Abstract idea"], c: 0, x: "Abstract ideas, laws of nature, and natural phenomena are the judicially-created exceptions — the battleground of Alice and Mayo." },
    { q: "A design patent's term is…", a: ["15 years from grant", "20 years from filing", "10 years from publication"], c: 0, x: "15 years from grant for applications filed after May 2015 (14 before that). No maintenance fees — unlike utility patents." },
    { q: "A 'Markman hearing' determines…", a: ["How the claims are construed — by the judge", "Damages — by the jury", "Inventorship disputes"], c: 0, x: "Markman v. Westview (1996): claim construction is a question of law for the court. Cases are often won or lost at this hearing." },
    { q: "The doctrine of equivalents lets a patentee reach…", a: ["Products outside the literal claim language", "Foreign sales", "Pre-issuance conduct"], c: 0, x: "Insubstantial differences don't avoid infringement — but prosecution history estoppel (what you gave up to get the patent) limits the doctrine's reach." },
    { q: "US applications generally publish…", a: ["18 months after the earliest filing date", "Immediately on filing", "Only when granted"], c: 0, x: "The 18-month publication rule — why patent attorneys joke they can't keep secrets. Non-publication requests exist but waive foreign filing." },
    { q: "Edison's lifetime count of US patents was roughly…", a: ["1,093", "350", "5,000"], c: 0, x: "A record for over a century — since lapped by modern prolific inventors like Shunpei Yamazaki and Lowell Wood, each past 1,300." },
    { q: "The US grace period lets an inventor file within…", a: ["1 year of their own public disclosure", "30 days of any disclosure", "5 years of conception"], c: 0, x: "One year — and it's a US peculiarity. Most of the world has absolute novelty: publish first, lose your foreign rights immediately." },
    { q: "An obviousness-type double patenting rejection is typically cured by…", a: ["A terminal disclaimer", "Paying a surcharge", "Canceling the spec"], c: 0, x: "The disclaimer ties the second patent's term (and ownership) to the first — you can extend your claim coverage but not your monopoly clock." },
    { q: "A PCT application gives you roughly how long to enter national phase?", a: ["30 months from priority", "12 months from filing", "5 years from publication"], c: 0, x: "30 (sometimes 31) months — the PCT is a delay-and-decide machine: one filing keeps ~150 countries open while you find money and markets." },
    { q: "'Means for fastening' in a claim invokes…", a: ["§112(f) — construed as the spec's structure + equivalents", "Automatic indefiniteness", "Broadest possible scope"], c: 0, x: "Means-plus-function claiming sounds broad but is cabined to what the specification actually discloses — a classic drafting trap." },
    { q: "The Wright brothers' patent war is often blamed for…", a: ["Stalling early US aviation until a WWI patent pool", "The invention of the jet engine", "The creation of the USPTO"], c: 0, x: "Litigation so fierce the US government forced a cross-licensing pool in 1917. Lesson: aggressive enforcement can freeze an industry." },
    { q: "Gordon Gould's fight over the laser patent lasted about…", a: ["30 years", "3 years", "6 months"], c: 0, x: "He noted 'LASER' in a 1957 notebook but lost the early filings race; decades of interference battles later, he finally collected royalties in the late 1980s." },
  ];

  // ── Content: Patent Jokes ─────────────────────────────────────────
  var PATENT_JOKES = [
    { s: "My patent attorney told me a great joke…", p: "I'd repeat it, but it's still pending." },
    { s: "Why don't patent attorneys keep secrets?", p: "Everything they know publishes at 18 months." },
    { s: "Why did the chicken cross the road?", p: "Obvious in view of Chicken et al. (1905). Rejected under §103." },
    { s: "Why was Claim 1 so lonely?", p: "All its dependents left for a continuation." },
    { s: "Prior art walked into a bar.", p: "The bartender said, \"I've seen you before.\"" },
    { s: "What did §101 say to the abstract idea?", p: "\"Adding 'on a computer' doesn't make you patentable.\"" },
    { s: "Why did the specification break up with the claims?", p: "No written support." },
    { s: "What's the hardest-working word in America?", p: "\"Wherein.\"" },
    { s: "Why do inventors fear anniversaries?", p: "Because provisionals expire at exactly 12 months." },
    { s: "What's an examiner's favorite dance?", p: "The §103 shuffle — combining references until something fits." },
    { s: "Why did the examiner reject the marriage proposal?", p: "\"About forever\" is indefinite, and \"said love\" lacks antecedent basis." },
    { s: "What's a restriction requirement?", p: "The USPTO's way of saying \"pick a lane.\"" },
    { s: "How does a patent attorney say \"close enough\"?", p: "\"The doctrine of equivalents.\"" },
    { s: "Why did the inventor bring a flashlight to the USPTO?", p: "Looking for a bright-line rule on eligibility. Still looking." },
  ];

  // ── Content: Patent of the Day — real patents, famous and absurd ──
  var PATENTS = [
    { no: "US 6,469", y: 1849, t: "Buoying Vessels Over Shoals", s: "Abraham Lincoln's device for lifting riverboats off sandbars — making him the only US president with a patent. It was never manufactured, but the model he whittled is in the Smithsonian." },
    { no: "US 174,465", y: 1876, t: "Improvement in Telegraphy", s: "Alexander Graham Bell's telephone patent — often called the most valuable patent ever issued. Bell's filing famously beat Elisha Gray's caveat for a similar invention at the Patent Office the very same day." },
    { no: "US 223,898", y: 1880, t: "Electric Lamp", s: "Edison's incandescent bulb with a carbonized filament. The patent survived years of litigation that established Edison didn't invent the lightbulb so much as the first one that actually worked — and the system to power it." },
    { no: "US 2,717,437", y: 1955, t: "Velvet Type Fabric (Velcro)", s: "George de Mestral examined the burrs stuck to his dog after a walk under a microscope, saw thousands of tiny hooks, and spent a decade making 'hook and loop' fasteners practical. The patent expired in 1978 — which is why everyone makes it now." },
    { no: "US 2,415,012", y: 1947, t: "Toy and Process of Use (Slinky)", s: "Naval engineer Richard James watched a torsion spring walk off a shelf and patented a 'helical spring toy.' Three hundred million Slinkys later, it's a lesson in claiming the use, not just the thing." },
    { no: "US 3,691,140", y: 1972, t: "Acrylate Copolymer Microspheres (Post-it)", s: "Spencer Silver patented a 'low-tack' adhesive nobody at 3M could find a use for — until Art Fry needed a bookmark that wouldn't fall out of his hymnal. The product launched twelve years after the patent." },
    { no: "US 3,351,836", y: 1967, t: "Intermittent Windshield Wiper", s: "Robert Kearns pitched his wiper to Ford, was turned away, then watched it appear on their cars. His decades-long infringement crusade won ~$30M and became the film 'Flash of Genius' — the patent system's great cautionary epic." },
    { no: "US 5,960,411", y: 1999, t: "1-Click Ordering", s: "Amazon's patent on buying with a single click — the poster child of the business-method patent era. Apple licensed it for the iTunes store rather than fight. It expired in 2017, and 'Buy Now' buttons bloomed everywhere overnight." },
    { no: "US 6,004,596", y: 1999, t: "Sealed Crustless Sandwich", s: "Smucker's patent behind Uncrustables. When they sued a small Michigan grocer over crimped PB&J, the resulting reexamination shredded the claims — prior art included, roughly, every grandmother." },
    { no: "AU 2001100012", y: 2001, t: "Circular Transportation Facilitation Device", s: "Australian patent attorney John Keogh patented the wheel to prove the new unexamined 'innovation patent' system would grant anything. IP Australia was not amused; the Ig Nobel committee was." },
    { no: "US 221,855", y: 1879, t: "Improvement in Fire-Escapes", s: "A parachute worn as a hat, paired with padded overshoes for landing. Benjamin Oppenheimer's drawing of a serene gentleman plummeting past a burning building remains one of the Patent Office's great artworks." },
    { no: "US 5,443,036", y: 1995, t: "Method of Exercising a Cat", s: "A granted patent on pointing a laser at the floor so a cat chases the dot. Exhibit A in every conversation about examination quality — and prior art known to every cat owner since the invention of the flashlight." },
    { no: "US 4,022,227", y: 1977, t: "Method of Concealing Partial Baldness", s: "A father-and-son team patented the comb-over: divide the remaining hair into three sections, sweep strategically. It won an Ig Nobel and immortality in §101 lectures." },
    { no: "US 6,360,693", y: 2002, t: "Animal Toy", s: "An 'apparatus for animal amusement' that is, on any fair reading of the claims, a stick. The USPTO later ordered reexamination. Dogs declined to comment on the validity of the prior art." },
    { no: "US 6,637,447", y: 2003, t: "Beerbrella", s: "A miniature umbrella that clips to a beer bottle to shade your beverage. Claim 1 is fully enabled, entirely novel at filing, and a standing reminder that patentable and profitable are different questions." },
    { no: "US 748,626", y: 1904, t: "The Landlord's Game", s: "Lizzie Magie patented the board game that became Monopoly — designed, ironically, to teach the evils of monopolies. Parker Brothers later bought her patent for about $500 and credited Charles Darrow instead." },
  ];

  // ── Content: Case of the Day — patent pool (default variant) ─────
  var CASES_PATENT = [
    { n: "Diamond v. Chakrabarty", y: 1980, s: "A GE engineer's oil-eating bacterium forced the question: can life be patented? The Court said yes — 'anything under the sun that is made by man' — and opened the door to the modern biotech industry." },
    { n: "Alice Corp. v. CLS Bank", y: 2014, s: "Claims to computerized escrow were an abstract idea, and adding 'do it on a computer' couldn't save them. The two-step Alice test has since invalidated thousands of software patents." },
    { n: "KSR v. Teleflex", y: 2007, s: "An adjustable gas pedal with an electronic sensor was obvious: the Court rejected rigid tests and blessed 'common sense' in combining references. §103 rejections got dramatically easier overnight." },
    { n: "Markman v. Westview", y: 1996, s: "Who decides what a claim means — judge or jury? The Court said judge, as a matter of law. The 'Markman hearing' it spawned is now often the whole ballgame in patent litigation." },
    { n: "Mayo v. Prometheus", y: 2012, s: "A method of adjusting drug doses by measuring metabolites claimed a law of nature, the Court held. The decision redrew §101 and still haunts diagnostics companies today." },
    { n: "AMP v. Myriad Genetics", y: 2013, s: "Isolated human genes are products of nature and not patentable — but lab-made cDNA is. Myriad's BRCA testing monopoly fell, and genetic test prices collapsed within months." },
    { n: "eBay v. MercExchange", y: 2006, s: "Winning infringement no longer means an automatic injunction — the traditional four-factor equity test applies. It defanged many patent trolls: payment, not shutdown." },
    { n: "Festo v. Shoketsu", y: 2002, s: "Narrow a claim during prosecution and you presumptively surrender the territory in between — prosecution history estoppel. The Court kept the bar flexible, but the lesson stands: every amendment costs scope." },
    { n: "Graham v. John Deere", y: 1966, s: "A plow shank case produced THE framework for obviousness — scope of prior art, differences, level of ordinary skill, secondary considerations — still governing every §103 fight sixty years on." },
    { n: "Phillips v. AWH", y: 2005, s: "The en banc Federal Circuit settled how claims are read: in light of the specification, through the eyes of a skilled artisan — dictionaries demoted. The most-cited claim construction case there is." },
    { n: "TC Heartland v. Kraft", y: 2017, s: "Patent venue means the defendant's state of incorporation or an established place of business. The Eastern District of Texas's reign as the patent-suit capital ended almost overnight." },
